--
-- Estructura de tabla para la tabla `horarios_semanales`
--

CREATE TABLE `horarios_semanales` (
  `id_horario` int(11) NOT NULL,
  `id_empleado` int(11) NOT NULL,
  `id_contrato` int(11) NOT NULL,
  `dia` enum('LUN','MAR','MIE','JUE','VIE','SAB','DOM') NOT NULL,
  `man_ini` time DEFAULT NULL,
  `man_fin` time DEFAULT NULL,
  `tar_ini` time DEFAULT NULL,
  `tar_fin` time DEFAULT NULL,
  `activo` tinyint(4) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

